with cleaned as (select *, ceil(sqft) as sqft_whole from stores where opened_date > to_date('2023-07-19') and store_name like '%Riversi%'), not_flagged as (select s.* from cleaned s where not exists (select 1 from store_sales ch where ch.store_id = s.id and ch.sale_date < s.opened_date)), kept as (select s.* from not_flagged s where not exists (select 1 from store_sales ch where ch.store_id = s.id and ch.sale_date <= s.opened_date)), latest_match as (select s.*, x.order_date, x.order_status from kept s left join lateral (select c.order_date, c.status as order_status from orders c where c.store_id = s.id order by c.amount desc, c.id desc limit 1) x on true), latest as (select * from latest_match qualify row_number() over (partition by region order by sqft, id) = 1) select date_trunc('week', order_date) as week_start, count(distinct id) as distinct_ids, size(collect_set(city)) as num_cities, count_if(city = 'Chiang Mai') as chiang_mai_events from latest group by week_start
